import { mockDatabase } from '../data/mockDatabase.js';
import { budgetRepository, groupRepository, piggyBankRepository, transactionRepository } from '../repositories/mock.js';
import { calculateSettlements } from '../services/debtSettlementService.js';
import { calculateEstimatedCompletion, calculatePercentage, calculateSavingsRate } from '../services/financeRules.js';
import { calculateGroupBalances, createSplits, groupFund } from '../services/groupFinanceService.js';
import { budgetSchema, creditCardSchema, groupContributionSchema, groupExpenseSchema, groupMemberSchema, groupSchema, movementSchema, piggySchema, transactionSchema } from '../validators/schemas.js';
import { notFound, ok } from '../utils/http.js';
const id = () => crypto.randomUUID();
const now = () => new Date().toISOString();
const routeId = (req) => Array.isArray(req.params.id) ? req.params.id[0] : req.params.id;
export const health = (_, res) => res.json({ status: 'ok', service: 'cofrin-api' });
export async function dashboard(_, res) { const transactions = await transactionRepository.list(); const income = transactions.filter(t => t.type === 'INCOME').reduce((a, t) => a + t.amount, 0); const expenses = transactions.filter(t => t.type === 'EXPENSE').reduce((a, t) => a + t.amount, 0); return ok(res, { totalBalance: 8420.35, income, expenses, committed: 1842.9, savingsRate: calculateSavingsRate(income, expenses), upcomingBills: transactions.filter(t => t.status === 'PENDING'), accounts: [{ name: 'Conta principal', balance: 6820.35 }, { name: 'Carteira', balance: 600 }, { name: 'Reserva', balance: 1000 }] }); }
export async function listTransactions(_, res) { return ok(res, await transactionRepository.list(), { total: mockDatabase.transactions.length }); }
export async function getTransaction(req, res) { const item = await transactionRepository.findById(routeId(req)); return item ? ok(res, item) : notFound(res, 'Transaction'); }
export async function createTransaction(req, res) { const value = transactionSchema.parse(req.body); const stamp = now(); const item = await transactionRepository.create({ id: id(), userId: 'u-joao', nature: 'PERSONAL', status: value.type === 'INCOME' ? 'RECEIVED' : 'PAID', recurrenceType: 'SINGLE', ...value, createdAt: stamp, updatedAt: stamp }); return res.status(201).json({ data: item }); }
export async function updateTransaction(req, res) { const value = transactionSchema.partial().parse(req.body); const item = await transactionRepository.update(routeId(req), { ...value, updatedAt: now() }); return item ? ok(res, item) : notFound(res, 'Transaction'); }
export async function removeTransaction(req, res) { return await transactionRepository.delete(routeId(req)) ? res.status(204).send() : notFound(res, 'Transaction'); }
export async function listPiggies(_, res) { return ok(res, await piggyBankRepository.list()); }
export async function getPiggy(req, res) { const item = await piggyBankRepository.findById(routeId(req)); if (!item)
    return notFound(res, 'Piggy bank'); return ok(res, { ...item, progress: calculatePercentage(item.currentAmount, item.targetAmount), forecast: calculateEstimatedCompletion(item.targetAmount, item.currentAmount, item.monthlyContribution ?? 0) }); }
export async function createPiggy(req, res) { const value = piggySchema.parse(req.body); const stamp = now(); const item = await piggyBankRepository.create({ id: id(), userId: 'u-joao', currentAmount: 0, status: 'ACTIVE', movements: [], ...value, createdAt: stamp, updatedAt: stamp }); return res.status(201).json({ data: item }); }
export async function updatePiggy(req, res) { const item = await piggyBankRepository.update(routeId(req), { ...piggySchema.partial().parse(req.body), updatedAt: now() }); return item ? ok(res, item) : notFound(res, 'Piggy bank'); }
export async function movePiggy(req, res) { const piggy = await piggyBankRepository.findById(routeId(req)); if (!piggy)
    return notFound(res, 'Piggy bank'); const movement = movementSchema.parse(req.body); const isDeposit = req.path.endsWith('deposits'); const amount = isDeposit ? movement.amount : -movement.amount; const next = Math.max(0, piggy.currentAmount + amount); const updated = await piggyBankRepository.update(piggy.id, { currentAmount: next, status: next >= piggy.targetAmount ? 'COMPLETED' : piggy.status, movements: [{ id: id(), piggyBankId: piggy.id, userId: 'u-joao', type: isDeposit ? 'DEPOSIT' : 'WITHDRAWAL', amount: movement.amount, date: movement.date ?? new Date().toISOString().slice(0, 10), description: movement.description, createdAt: now() }, ...piggy.movements], updatedAt: now() }); return ok(res, updated); }
export async function listGroups(_, res) { return ok(res, await groupRepository.list()); }
export async function getGroup(req, res) { const item = await groupRepository.findById(routeId(req)); return item ? ok(res, item) : notFound(res, 'Group'); }
export async function createGroup(req, res) { const value = groupSchema.parse(req.body); const stamp = now(); const groupId = id(); const item = await groupRepository.create({ id: groupId, ownerId: 'u-joao', status: 'ACTIVE', members: [{ id: id(), groupId, userId: 'u-joao', name: 'João Braga', role: 'OWNER', expectedContribution: 0, joinedAt: stamp, status: 'ACTIVE', balance: 0 }], contributions: [], expenses: [], settlements: [], ...value, createdAt: stamp, updatedAt: stamp }); return res.status(201).json({ data: item }); }
export async function updateGroup(req, res) { const item = await groupRepository.update(routeId(req), { ...groupSchema.partial().parse(req.body), updatedAt: now() }); return item ? ok(res, item) : notFound(res, 'Group'); }
export async function groupMembers(req, res) { const item = await groupRepository.findById(routeId(req)); return item ? ok(res, item.members) : notFound(res, 'Group'); }
export async function addGroupMember(req, res) { const group = await groupRepository.findById(routeId(req)); if (!group)
    return notFound(res, 'Group'); const value = groupMemberSchema.parse(req.body); if (group.members.some(member => member.userId === value.userId))
    return res.status(409).json({ error: { code: 'CONFLICT', message: 'Member already belongs to this group.' } }); const member = { id: id(), groupId: group.id, joinedAt: now(), status: 'ACTIVE', balance: 0, ...value }; await groupRepository.update(group.id, { members: [...group.members, member], updatedAt: now() }); return res.status(201).json({ data: member }); }
export async function groupContributions(req, res) { const group = await groupRepository.findById(routeId(req)); return group ? ok(res, group.contributions) : notFound(res, 'Group'); }
export async function addGroupContribution(req, res) { const group = await groupRepository.findById(routeId(req)); if (!group)
    return notFound(res, 'Group'); const value = groupContributionSchema.parse(req.body); if (!group.members.some(member => member.userId === value.userId))
    return res.status(400).json({ error: { code: 'VALIDATION_ERROR', message: 'Contributor is not an active group member.' } }); const contribution = { id: id(), groupId: group.id, date: value.date ?? new Date().toISOString().slice(0, 10), createdAt: now(), ...value }; await groupRepository.update(group.id, { contributions: [...group.contributions, contribution], updatedAt: now() }); return res.status(201).json({ data: contribution }); }
export async function groupExpenses(req, res) { const group = await groupRepository.findById(routeId(req)); return group ? ok(res, group.expenses) : notFound(res, 'Group'); }
export async function addGroupExpense(req, res) { const group = await groupRepository.findById(routeId(req)); if (!group)
    return notFound(res, 'Group'); const value = groupExpenseSchema.parse(req.body); if (!group.members.some(member => member.userId === value.paidByUserId))
    return res.status(400).json({ error: { code: 'VALIDATION_ERROR', message: 'Payer is not an active group member.' } }); const expenseId = id(); const participants = value.participants ?? group.members.filter(member => member.status === 'ACTIVE').map(member => ({ userId: member.userId })); const expense = { id: expenseId, groupId: group.id, description: value.description, amount: value.amount, paidByUserId: value.paidByUserId, date: value.date ?? new Date().toISOString().slice(0, 10), category: value.category, splitType: value.splitType, paymentSource: value.paymentSource, notes: value.notes, splits: createSplits(expenseId, value.amount, participants.map(item => item.userId), value.splitType, participants), createdAt: now() }; await groupRepository.update(group.id, { expenses: [...group.expenses, expense], updatedAt: now() }); return res.status(201).json({ data: expense }); }
export async function groupBalances(req, res) { const group = await groupRepository.findById(routeId(req)); return group ? ok(res, calculateGroupBalances(group)) : notFound(res, 'Group'); }
export async function groupSettlements(req, res) { const group = await groupRepository.findById(routeId(req)); return group ? ok(res, calculateSettlements(calculateGroupBalances(group))) : notFound(res, 'Group'); }
export async function markSettlementPaid(req, res) { const group = await groupRepository.findById(routeId(req)); if (!group)
    return notFound(res, 'Group'); const settlement = group.settlements.find(item => item.id === req.params.settlementId); if (!settlement)
    return notFound(res, 'Settlement'); settlement.status = 'PAID'; settlement.settledAt = now(); return ok(res, settlement); }
export async function groupSummary(req, res) { const group = await groupRepository.findById(routeId(req)); if (!group)
    return notFound(res, 'Group'); const balances = calculateGroupBalances(group); return ok(res, { group, fund: groupFund(group), totalContributed: group.contributions.filter(c => c.status === 'CONFIRMED').reduce((total, c) => total + c.amount, 0), totalExpenses: group.expenses.reduce((total, e) => total + e.amount, 0), balances, settlements: calculateSettlements(balances) }); }
export async function listBudgets(_, res) { return ok(res, await budgetRepository.list()); }
export async function createBudget(req, res) { const value = budgetSchema.parse(req.body); const stamp = now(); const item = await budgetRepository.create({ id: id(), userId: 'u-joao', currentAmount: 0, ...value, createdAt: stamp, updatedAt: stamp }); return res.status(201).json({ data: item }); }
export async function updateBudget(req, res) { const item = await budgetRepository.update(routeId(req), { ...budgetSchema.partial().parse(req.body), updatedAt: now() }); return item ? ok(res, item) : notFound(res, 'Budget'); }
export async function removeBudget(req, res) { return await budgetRepository.delete(routeId(req)) ? res.status(204).send() : notFound(res, 'Budget'); }
export const listCards = (_, res) => ok(res, mockDatabase.creditCards);
export const createCard = (req, res) => { const value = creditCardSchema.parse(req.body); const item = { id: id(), userId: 'u-joao', color: '#a78bfa', isActive: true, createdAt: now(), updatedAt: now(), ...value }; mockDatabase.creditCards.push(item); return res.status(201).json({ data: item }); };
export const invoices = (_, res) => ok(res, { currentInvoice: 1243.31, nextInvoice: 980, futureInvoices: [754, 612] });
export const listNotifications = (_, res) => ok(res, mockDatabase.notifications);
export const readNotification = (req, res) => { const item = mockDatabase.notifications.find(n => n.id === routeId(req)); if (!item)
    return notFound(res, 'Notification'); item.read = true; return ok(res, item); };
